import * as T from 'three';
import {GLTFLoader} from '/sandbox2-runtime/vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '/sandbox2-runtime/vendor/OrbitControls.js';
import {sandboxWheel} from '/sandbox-camera.mjs';
const $=id=>document.getElementById(id),canvas=document.querySelector('canvas'),stage=$('stage');
const renderer=new T.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;
const scene=new T.Scene();scene.background=new T.Color('#f4e9d5');scene.fog=new T.Fog('#f4e9d5',16,40);
const camera=new T.PerspectiveCamera(38,1,.02,100),orbit=new OrbitControls(camera,canvas);orbit.enableDamping=false;orbit.minDistance=1.2;orbit.maxDistance=35;orbit.maxPolarAngle=Math.PI*.49;orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};
canvas.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});canvas.addEventListener('pointerdown',e=>{orbit.mouseButtons.LEFT=e.shiftKey?T.MOUSE.PAN:T.MOUSE.ROTATE;},{capture:true});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function fit(){camera.position.set(3.0,2.1,4.5);orbit.target.set(0,.9,0);if(camera.aspect<1)camera.position.sub(orbit.target).multiplyScalar(1.2).add(orbit.target);orbit.update();}$('fit').onclick=fit;fit();new ResizeObserver(()=>{const r=stage.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();fit();}).observe(stage);
scene.add(new T.HemisphereLight('#dceafa','#59635b',2));const key=new T.DirectionalLight('#fff0d3',3);key.position.set(3,6,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-5;key.shadow.camera.right=5;key.shadow.camera.top=5;key.shadow.camera.bottom=-5;scene.add(key);const rim=new T.DirectionalLight('#80c5dc',2);rim.position.set(-3,3,-3);scene.add(rim);
const floor=new T.Mesh(new T.PlaneGeometry(60,60),new T.MeshStandardMaterial({color:'#e5d8bd',roughness:.95}));floor.rotation.x=-Math.PI/2;floor.position.y=-.008;floor.receiveShadow=true;scene.add(floor);
let mixer,actor,active,clips=[],paused=false,loadId=0;const once=new Set(['attack','defend','celebrate','perish']);
function select(name){const c=clips.find(c=>c.name===name);if(!c)return;const next=mixer.clipAction(c);next.reset().setEffectiveTimeScale(1).setEffectiveWeight(1).setLoop(once.has(name)?T.LoopOnce:T.LoopRepeat,Infinity);next.clampWhenFinished=true;next.play();if(active&&active!==next){active.crossFadeTo(next,.22,false);}active=next;paused=false;$('play').textContent='Pause';$('scrub').max=c.duration;$('status').textContent=$('model').selectedOptions[0].textContent+' · '+name;$('mode').textContent=(once.has(name)?'Plays once · holds final pose':'Loops continuously')+' · '+c.duration.toFixed(2)+' s';document.querySelectorAll('#clips button').forEach(b=>b.setAttribute('aria-pressed',b.textContent===name));}
async function load(){const id=++loadId;$('status').textContent='Loading…';try{const g=await new GLTFLoader().loadAsync('/greek-animation-b-assets/'+$('model').value+'.glb');if(id!==loadId)return;if(actor){scene.remove(actor);mixer.stopAllAction();}actor=g.scene;actor.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});scene.add(actor);mixer=new T.AnimationMixer(actor);clips=g.animations;active=null;$('clips').replaceChildren(...['walk','idle 1','idle 2','idle 3','attack','defend','celebrate','perish','rest'].map(name=>{const b=document.createElement('button');b.textContent=name;b.disabled=!clips.some(c=>c.name===name);b.onclick=()=>select(name);return b;}));select('idle 1');}catch(e){$('status').textContent='Load failed: '+e.message;}}
$('model').onchange=load;$('play').onclick=()=>{paused=!paused;$('play').textContent=paused?'Play':'Pause';};$('replay').onclick=()=>select(active.getClip().name);$('scrub').oninput=()=>{mixer.stopAllAction();active.reset().play();active.time=+$('scrub').value;mixer.update(0);paused=true;$('play').textContent='Play';};$('help').onclick=()=>$('about').showModal();$('close').onclick=()=>$('about').close();
function appearance(){const s=getComputedStyle(document.body);const bg=s.getPropertyValue('--app-canvas').trim();if(bg){scene.background.set(bg);scene.fog.color.set(bg);floor.material.color.set(bg);}}window.addEventListener('app-style-change',appearance);appearance();
window.animationStudy={get state(){return {model:$('model').value,clips:clips.map(c=>({name:c.name,duration:c.duration,tracks:c.tracks.length})),clip:active?.getClip().name,time:active?.time,paused};},select};
let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(mixer&&!paused&&!document.hidden)mixer.update(dt*Number($('speed').value));if(active){$('scrub').value=active.time;$('time').textContent=active.time.toFixed(2)+' s';}renderer.render(scene,camera);requestAnimationFrame(frame);}load();requestAnimationFrame(frame);
